#include <stdio.h>
int main() {
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    int max_d = 0;
    for (int i = 0; s[i]; i++) if (s[i] - '0' > max_d) max_d = s[i] - '0';
    printf("%d\n", max_d + 1);
    return 0;
}

