code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            int maxD = 0;
            for (char c : s.toCharArray()) if (c - '0' > maxD) maxD = c - '0';
            System.out.println(maxD + 1);
        }
    }
}

